from __future__ import annotations

import re

from duplicate_guard import username_is_duplicate

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


def screen_candidate(record, username_snapshot):
    errors = []
    for field in ("name", "email", "username"):
        if field not in record:
            errors.append({"field": field, "reason": "missing"})
        elif record[field] == "":
            errors.append({"field": field, "reason": "empty"})

    if "email" in record and record["email"] != "" and not EMAIL_RE.match(record["email"]):
        errors.append({"field": "email", "reason": "format"})

    if (
        "username" in record
        and record["username"] != ""
        and username_is_duplicate(record["username"], username_snapshot)
    ):
        errors.append({"field": "username", "reason": "duplicate"})

    return errors
